/* An Lạc Đường — V1.6 · Original licensed-in-project meditation soundtrack. */
(()=>{'use strict';
const $=sel=>document.querySelector(sel);
const panel=$('#musicPanel'),button=$('#musicToggle'),select=$('#musicTrackSelect');
if(!panel||!button||!select)return;
const status=$('#musicStatus'),title=$('#musicTrackTitle'),credit=$('#musicCredit'),source=$('#musicSource');
const vol=$('#musicVolume'),volText=$('#musicVolumeValue'),fileInput=$('#musicFile'),sound=$('#soundButton');
const tracks=[
{name:'Chuông Sớm An Nhiên',src:'data:audio/mpeg;base64,'},
{name:'Sen Nở Trong Tâm',src:'data:audio/mpeg;base64,'},
{name:'Hương Trầm Tĩnh Lặng',src:'data:audio/mpeg;base64,'}
];
const player=new Audio();player.preload='none';player.volume=.46;
let index=0,enabled=false,blob=null,wasStarted=false;
for(let i=0;i<tracks.length;i++){const option=document.createElement('option');option.value=String(i);option.textContent=tracks[i].name;select.append(option)}
const getTrack=()=>tracks[index];
function message(msg,warn=false){status.textContent=msg;status.classList.toggle('music-warn',warn)}
function paint(){title.textContent=blob?'Nhạc từ thiết bị':getTrack().name;credit.textContent=blob?'Nhạc của bạn · chỉ có trên thiết bị này':'Nhạc thiền nguyên bản · An Lạc Đường';source.removeAttribute('href');source.textContent='Giai điệu nguyên bản được phát trực tiếp trong website';select.value=blob?'':String(index);button.textContent=!player.paused&&enabled?'❚❚ Tạm dừng':'▶ Phát nhạc';sound?.classList.toggle('music-active',!player.paused&&enabled)}
function open(){panel.classList.remove('hidden');sound?.setAttribute('aria-expanded','true')}
function close(){panel.classList.add('hidden');sound?.setAttribute('aria-expanded','false')}
async function play(){if(!player.src){player.src=blob||getTrack().src;player.load()};enabled=true;try{await player.play();message('Đang phát nhạc thiền')}catch(e){enabled=false;message('Trình duyệt chưa cho phát. Vui lòng chạm nút Phát nhạc rồi kiểm tra âm lượng.',true);open()}paint()}
function pause(){enabled=false;player.pause();message('Đã tạm dừng');paint()}
function switchTrack(n,autoplay=true){index=(n+tracks.length)%tracks.length;if(blob){URL.revokeObjectURL(blob);blob=null}player.pause();enabled=false;player.removeAttribute('src');player.load();paint();if(autoplay)play()}
button.addEventListener('click',()=>enabled?pause():play());
$('#musicPrevious')?.addEventListener('click',()=>switchTrack(index-1));
$('#musicNext')?.addEventListener('click',()=>switchTrack(index+1));
$('#musicClose')?.addEventListener('click',close);
select.addEventListener('change',()=>switchTrack(Number(select.value)));
vol.addEventListener('input',()=>{player.volume=Number(vol.value)/100;volText.textContent=vol.value+'%'});
fileInput?.addEventListener('change',e=>{const f=e.target.files?.[0];if(!f)return;if(!f.type.startsWith('audio/')){message('Vui lòng chọn file MP3, M4A hoặc OGG',true);return}player.pause();if(blob)URL.revokeObjectURL(blob);blob=URL.createObjectURL(f);player.removeAttribute('src');player.src=blob;enabled=false;paint();play()});
player.addEventListener('ended',()=>{if(enabled&&!blob)switchTrack(index+1);else if(enabled&&blob){player.currentTime=0;play()}});
player.addEventListener('error',()=>{enabled=false;paint();message('Lỗi phát nhạc: bấm Phát lại hoặc chuyển bài.',true);open()});
player.addEventListener('playing',()=>{enabled=true;paint();message('Đang phát nhạc thiền')});
window.AnLacMusic={startOnEntry(){if(!wasStarted){wasStarted=true;play()}},pause,play,open,togglePanel(){panel.classList.contains('hidden')?open():close()},tracks};
paint();message('Nhạc thiền không lời đã sẵn sàng. Bấm Vào chùa hoặc nút Phát.');
})();
